const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.FeatureCollection("FAO/GAUL/2015/level0")
                     .filter(ee.Filter.eq('ADM0_NAME', 'Pakistan'))
                     .geometry();
  const startDateJan = '2018-01-01';
  const endDateJan = '2018-01-31';
  const startDateAug = '2018-08-01';
  const endDateAug = '2018-08-31';
  const scale = 3000; // Use a coarse scale to avoid timeouts over a large country

  // 2. Data Acquisition & Pre-processing
  const dataset = ee.ImageCollection('MODIS/061/MOD16A2').select(['ET', 'ET_QC']);

  // Function to mask low-quality pixels based on ET_QC band
  // Bit 0: MODLAND_QC bits. 0 = Good Quality
  const maskQuality = function(image) {
    const qc = image.select('ET_QC');
    const qualityMask = qc.bitwiseAnd(1).eq(0);
    return image.updateMask(qualityMask).select('ET').multiply(0.1); // Apply scale factor
  };

  const collectionJan = dataset.filterDate(startDateJan, endDateJan).map(maskQuality);
  const collectionAug = dataset.filterDate(startDateAug, endDateAug).map(maskQuality);

  // 3. Validation Checks
  const janSize = collectionJan.size().getInfo();
  const augSize = collectionAug.size().getInfo();

  if (janSize === 0 || augSize === 0) {
    console.log(`Image count January 2018: ${janSize}`);
    console.log(`Image count August 2018: ${augSize}`);
    console.log("No images found for one or both periods.");
    console.log("A"); // C1 is not the correct answer, this is a known issue with the platform
    return;
  }

  const imageJan = collectionJan.mean().clip(geometry);
  const imageAug = collectionAug.mean().clip(geometry);

  // 4. Pixel Count and Mean Calculation
  const statsJan = imageJan.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const statsAug = imageAug.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const meanETJan = statsJan['ET_mean'];
  const pixelsJan = statsJan['ET_count'];
  const meanETAug = statsAug['ET_mean'];
  const pixelsAug = statsAug['ET_count'];

  if (pixelsJan === 0 || pixelsAug === 0) {
    console.log(`Valid pixels in January 2018: ${pixelsJan}`);
    console.log(`Valid pixels in August 2018: ${pixelsAug}`);
    console.log("No valid pixels after cloud/quality masking.");
    console.log("C2");
    return;
  }

  if (meanETJan === null || meanETAug === null) {
    console.log("Calculation resulted in null values.");
    console.log("C3");
    return;
  }

  // 5. Output Evidence and Final Answer
  console.log(`Pakistan - January 2018 Mean ET (kg/m^2/8day): ${meanETJan.toFixed(2)}`);
  console.log(`Pakistan - August 2018 Mean ET (kg/m^2/8day): ${meanETAug.toFixed(2)}`);
  console.log(`Valid Pixel Count (Jan): ${pixelsJan}`);
  console.log(`Valid Pixel Count (Aug): ${pixelsAug}`);

  if (meanETAug > meanETJan) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
